const items = $input.all();
const processedItems = [];

for (const item of items) {
  const websiteData = item.json;


  let scrapingSuccessful = false;
  let extractedContent = {};

  if (websiteData.error) {
    // Scraping failed
    scrapingSuccessful = false;
  } else {
    // Extract content from HTML
    const html = websiteData.data || '';

    // Simple extraction patterns
    const titleMatch = html.match(/<title>([^<]+)<\/title>/i);
    const metaDescMatch = html.match(/<meta\s+name=["']description["']\s+content=["']([^"']+)["']/i);

    // Extract text content (remove scripts and styles)
    let textContent = html
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    // Look for common patterns
    const aboutMatches = textContent.match(/about\s+us[\s\S]{0,500}/i);
    const servicesMatches = textContent.match(/services?[\s\S]{0,500}/i);
    const faqMatches = textContent.match(/faq|frequently\s+asked[\s\S]{0,1000}/i);

    extractedContent = {
      title: titleMatch ? titleMatch[1] : originalData.businessName,
      description: metaDescMatch ? metaDescMatch[1] : '',
      aboutText: aboutMatches ? aboutMatches[0].substring(0, 300) : '',
      servicesText: servicesMatches ? servicesMatches[0].substring(0, 300) : '',
      faqText: faqMatches ? faqMatches[0].substring(0, 500) : '',
      rawTextSample: textContent.substring(0, 1000)
    };

    scrapingSuccessful = Object.values(extractedContent).some(v => v && v.length > 50);
  }

  processedItems.push({
    json: {

      scrapingSuccessful,
      extractedContent,
      kbCreationStatus: scrapingSuccessful ? 'pending_website_data' : 'pending_generic_data'
    }
  });
}

return processedItems;

