const items = $input.all();   // همه رکوردها از نود قبل
const now = new Date();

return items.map(item => {
  const dbDate = new Date(item.json.date);
  const diff = now.getTime() - dbDate.getTime();
  const hoursPassed = diff / (1000 * 60 * 60);

  return {
    json: {
      ...item.json, // داده‌های قبلی هم نگه داریم
      dbDate: dbDate.toISOString(),
      now: now.toISOString(),
      hoursPassed,
      Email : item.json.Email,
      passed24h: hoursPassed >= 24
    }
  };
});

